// src/format/index.ts
var HTML_ESCAPE_PATTERN = /[&<>"]/g;
var HTML_TAG_PATTERN = /<[^>]{1,2048}>/g;
var MARKDOWN_LINK_PATTERN = /\[([^\]]+)\]\(([^)]+)\)/g;
var TEAMS_MENTION_PATTERN = /<at\b[^>]*>(.*?)<\/at>/gis;
var HTML_ESCAPES = {
  '"': "&quot;",
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;"
};
var EMOJI_PLACEHOLDERS = {
  ":red_circle:": "\u{1F534}",
  ":warning:": "\u26A0\uFE0F",
  ":white_check_mark:": "\u2705",
  ":x:": "\u274C"
};
var SAFE_LINK_PROTOCOLS = /* @__PURE__ */ new Set(["http:", "https:", "mailto:"]);
function escapeTeamsText(text) {
  return text.replace(
    HTML_ESCAPE_PATTERN,
    (char) => HTML_ESCAPES[char] ?? char
  );
}
function unescapeTeamsText(text) {
  return text.replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
}
function formatTeamsMention(name) {
  return `<at>${escapeTeamsText(name)}</at>`;
}
function teamsMentionToPlainText(text) {
  return text.replace(TEAMS_MENTION_PATTERN, (_match, name) => {
    return `@${unescapeTeamsText(stripHtmlTags(name).trim())}`;
  });
}
function teamsHtmlToMarkdown(html) {
  const withoutTags = stripHtmlTags(
    teamsMentionToPlainText(html).replace(/<strong\b[^>]*>(.*?)<\/strong>/gis, "**$1**").replace(/<b\b[^>]*>(.*?)<\/b>/gis, "**$1**").replace(/<em\b[^>]*>(.*?)<\/em>/gis, "_$1_").replace(/<i\b[^>]*>(.*?)<\/i>/gis, "_$1_").replace(/<s\b[^>]*>(.*?)<\/s>/gis, "~~$1~~").replace(/<strike\b[^>]*>(.*?)<\/strike>/gis, "~~$1~~").replace(/<code\b[^>]*>(.*?)<\/code>/gis, "`$1`").replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gis, "[$2]($1)").replace(/<br\s*\/?>/gi, "\n").replace(/<\/p>\s*<p[^>]*>/gi, "\n\n")
  );
  return unescapeTeamsText(withoutTags.replace(/\u00a0/g, " ")).trim();
}
function markdownToTeamsHtml(markdown) {
  return convertTeamsEmojiPlaceholders(escapeTeamsText(markdown)).replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>").replace(/_(.*?)_/g, "<em>$1</em>").replace(/~~(.*?)~~/g, "<s>$1</s>").replace(/`([^`]+)`/g, "<code>$1</code>").replace(
    MARKDOWN_LINK_PATTERN,
    (_match, label, href) => safeLinkHref(href) ? `<a href="${href}">${label}</a>` : label
  ).replace(/\n/g, "<br>");
}
function convertTeamsEmojiPlaceholders(text) {
  let converted = text;
  for (const [placeholder, emoji] of Object.entries(EMOJI_PLACEHOLDERS)) {
    converted = converted.replaceAll(placeholder, emoji);
  }
  return converted;
}
function stripHtmlTags(text) {
  let current = text;
  let previous;
  do {
    previous = current;
    current = current.replace(HTML_TAG_PATTERN, "");
  } while (current !== previous);
  return current;
}
function safeLinkHref(href) {
  try {
    return SAFE_LINK_PROTOCOLS.has(new URL(href).protocol);
  } catch {
    return false;
  }
}

export {
  escapeTeamsText,
  unescapeTeamsText,
  formatTeamsMention,
  teamsMentionToPlainText,
  teamsHtmlToMarkdown,
  markdownToTeamsHtml,
  convertTeamsEmojiPlaceholders,
  stripHtmlTags
};
